INSERT INTO chunks (id,document_id,title,heading,body,audience,status,version,effective_date) VALUES ('returns-0-0','returns','İade politikası','Kural ve koşullar','Standart iade süresi teslimattan itibaren 30 takvim günüdür. İade talebinde sipariş numarası ve teslim tarihi gerekir. Kullanılmış sarf malzemeleri iade kapsamı dışındadır.','public','current',2,'2026-09-01');
INSERT INTO chunks_fts (id,title,heading,body) VALUES ('returns-0-0','İade politikası','Kural ve koşullar','Standart iade süresi teslimattan itibaren 30 takvim günüdür. İade talebinde sipariş numarası ve teslim tarihi gerekir. Kullanılmış sarf malzemeleri iade kapsamı dışındadır.');
INSERT INTO chunks (id,document_id,title,heading,body,audience,status,version,effective_date) VALUES ('returns-1-0','returns','İade politikası','Uygulama ve takip','Bu prosedür Aster Mobility''nin Türkiye operasyonlarında kullanılır. İade politikası için kayıt oluşturulurken müşteri ve işlem bilgisi doğrulanır. İşlem kaydı ilgili ekibe atanır; eksik bilgi varsa müşteriden tamamlaması istenir. Sonuç destek portalında müşteriye bildirilir. Tatil günleri iş günü hesaplamasına dahil edilmez. Kapsamı aşan durumlarda yetkili ekibe danışılır; belgede tanımlanmayan hak veya süre taahhüt edilmez.','public','current',2,'2026-09-01');
INSERT INTO chunks_fts (id,title,heading,body) VALUES ('returns-1-0','İade politikası','Uygulama ve takip','Bu prosedür Aster Mobility''nin Türkiye operasyonlarında kullanılır. İade politikası için kayıt oluşturulurken müşteri ve işlem bilgisi doğrulanır. İşlem kaydı ilgili ekibe atanır; eksik bilgi varsa müşteriden tamamlaması istenir. Sonuç destek portalında müşteriye bildirilir. Tatil günleri iş günü hesaplamasına dahil edilmez. Kapsamı aşan durumlarda yetkili ekibe danışılır; belgede tanımlanmayan hak veya süre taahhüt edilmez.');
