INSERT INTO chunks (id,document_id,title,heading,body,audience,status,version,effective_date) VALUES ('training-1-0','training','Kullanıcı eğitimi','Uygulama ve takip','Bu prosedür Aster Mobility''nin Türkiye operasyonlarında kullanılır. Kullanıcı eğitimi için kayıt oluşturulurken müşteri ve işlem bilgisi doğrulanır. İşlem kaydı ilgili ekibe atanır; eksik bilgi varsa müşteriden tamamlaması istenir. Sonuç destek portalında müşteriye bildirilir. Tatil günleri iş günü hesaplamasına dahil edilmez. Kapsamı aşan durumlarda yetkili ekibe danışılır; belgede tanımlanmayan hak veya süre taahhüt edilmez.','public','current',2,'2026-09-01');
INSERT INTO chunks_fts (id,title,heading,body) VALUES ('training-1-0','Kullanıcı eğitimi','Uygulama ve takip','Bu prosedür Aster Mobility''nin Türkiye operasyonlarında kullanılır. Kullanıcı eğitimi için kayıt oluşturulurken müşteri ve işlem bilgisi doğrulanır. İşlem kaydı ilgili ekibe atanır; eksik bilgi varsa müşteriden tamamlaması istenir. Sonuç destek portalında müşteriye bildirilir. Tatil günleri iş günü hesaplamasına dahil edilmez. Kapsamı aşan durumlarda yetkili ekibe danışılır; belgede tanımlanmayan hak veya süre taahhüt edilmez.');
INSERT INTO chunks (id,document_id,title,heading,body,audience,status,version,effective_date) VALUES ('training-2-0','training','Kullanıcı eğitimi','Sürüm notu','Bu belgenin ikinci sürümü 1 Eylül 2026 itibarıyla geçerlidir. Önceki sürüm arşivlenmiştir. Belge numarası AST-008. Şirket, kişiler ve kurallar RAGNA testleri için kurgulanmıştır; gerçek ticari koşulları temsil etmez.','public','current',2,'2026-09-01');
