INSERT INTO chunks (id,document_id,title,heading,body,audience,status,version,effective_date) VALUES ('maintenance-0-0','maintenance','Bakım aralığı','Kural ve koşullar','Aster M200 için periyodik bakım her 6 ayda veya 500 çalışma saatinde yapılır; önce dolan sınır geçerlidir. Tozlu ortamlarda filtreler her ay kontrol edilir. Bakım kaydı servis portalında saklanır.','public','current',2,'2026-09-01');
