INSERT INTO chunks (id,document_id,title,heading,body,audience,status,version,effective_date) VALUES ('remote-0-0','remote','Uzaktan erişim','Kural ve koşullar','Uzaktan servis oturumu müşteri onayı ile başlatılır. Her oturum en fazla 60 dakika sürer ve otomatik kapanır. Kalıcı erişim hesabı açılmaz. Oturum kaydı yalnızca yetkili servis yöneticileri tarafından görüntülenebilir.','public','current',2,'2026-09-01');
