INSERT INTO chunks (id,document_id,title,heading,body,audience,status,version,effective_date) VALUES ('escalation-0-0','escalation','Şikayet eskalasyonu','Kural ve koşullar','Çözülemeyen müşteri şikayetleri 2 iş günü sonunda müşteri başarı yöneticisine aktarılır. Şikayet kayıt numarası ve önceki aksiyonlar eklenir. P1 teknik olayları bu süreyi beklemeden öncelikli destek sürecine girer.','public','current',2,'2026-09-01');
